PAGE = 4096                              # 4 KB pages: the low 12 bits are the offset
page_table = {0: 5, 1: 9, 2: None, 3: 2}  # page -> frame; None = valid page, not in RAM now


def translate(vaddr):
    page, offset = divmod(vaddr, PAGE)
    where = f"virtual {vaddr:>5} = page {page}, offset {offset:>4}"
    if page not in page_table:
        return where + " -> invalid address (segmentation fault)"
    frame = page_table[page]
    if frame is None:
        return where + " -> page fault: OS loads it, then retries"
    return where + f" -> frame {frame}, physical {frame * PAGE + offset}"


for v in [100, 4100, 8200, 13000, 20000]:
    print(translate(v))
